-- ----------------------------
-- Table structure for article
-- ----------------------------
DROP TABLE IF EXISTS `article`;
CREATE TABLE `article`  (
  `article_id` mediumint(8) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '文章id：[0,8388607]',
  `title` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题：[0,125]用于文章和html的title标签中',
  `type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '文章分类：[0,1000]用来搜索指定类型的文章',
  `hits` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '点击数：[0,1000000000]访问这篇文章的人次',
  `praise_len` int(11) NOT NULL DEFAULT 0 COMMENT '点赞数',
  `create_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间：',
  `update_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间：',
  `source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源：[0,255]文章的出处',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源地址：[0,255]用于跳转到发布该文章的网站',
  `tag` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签：[0,255]用于标注文章所属相关内容，多个标签用空格隔开',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '正文：文章的主体内容',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '封面图',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '文章描述',
  PRIMARY KEY (`article_id`, `title`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文章：用于内容管理系统的文章' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of article
-- ----------------------------
INSERT INTO `article` VALUES (1, '杜锋：伤的伤停赛的停赛 只要进季后赛就可以', '运动', 535, 0, '2022-02-27 02:36:06', '2022-02-27 02:36:06', NULL, NULL, NULL, '<p class=\"ql-align-justify\">直播吧1月15日讯 CBA常规赛今天继续进行，广东男篮94比114不敌广厦男篮。赛后主教练<a href=\"https://www.163.com/keywords/6/5/675c950b/1.html\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 140, 210);\">杜锋</a>接受了媒体的采访。</p><p class=\"ql-align-justify\">杜锋谈到了这场失利：“球队现在进入了一个比较困难的时期，人员伤的伤、<a href=\"https://www.163.com/keywords/5/5/505c8d5b/1.html\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 140, 210);\">停赛</a>的停赛、生病的生病，周鹏、二飞、阿联和<a href=\"https://www.163.com/keywords/8/c/82cf4f1f/1.html\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 140, 210);\">苏伟</a>都是带伤在打球，越来越困难，但是我觉得大家在场上的态度还是非常好的。这个赛季的第二次两连败吧，输球倒问题不大，其实也说了，只要进季后赛就可以。希望在比赛过程当中年轻队员有更多的收获，特别是徐杰也好，还有小胡，希望他们通过比赛更快的成长起来，如果这样的话，输球就有价值。”</p>', '/api/upload/image_1642762283729.jpg', '2022年03月23日 12:51 新浪网');
INSERT INTO `article` VALUES (2, '休斯顿1 3号退役，5 8先生亲自上阵技巧大赛', '运动', 589, 0, '2022-02-27 02:36:06', '2022-02-27 02:36:06', NULL, NULL, NULL, '<p>从雷霆仅仅因几百万交易走哈登来到休斯顿连续闯入八年季后赛两次进入西部决赛为整支球队带来很大的成功也给广大火箭粉丝们创造许多回忆</p><p><br></p><p><strong>“詹姆斯-哈登永远都是一个火箭人。我们当然会退役他的球衣，他让我拥有这支球队前三年的经历变得难忘。他效力的8年间给这支球队带来了很大的成功，为我们的球迷和社区创造了很多回忆。”</strong></p><p>火箭老板费尔蒂塔近日官宣，球队将来会退役哈登在火箭队的13号球衣。</p><p><br></p><p>火箭老板能发表退役哈登球衣打破所有质疑也是意料之中，此前有6位在熟悉不过的中国的长城大姚还有队史第一，大梦都是名人堂球员，足以说明詹姆斯·哈登的伟大无需多言</p><p><br></p><p>火箭依旧是哈登的家，火箭管理层说哪怕在篮网能拿一两个冠军，只要回家都会为你开门，重回休斯顿变身救世主咋感觉有点勒布朗的味道不吹不黑，果然，叫詹姆斯的男人都牛皮</p><p><br></p><p>老板的官宣打破了所有质疑声明个哈登篮网首发作战老东家哈登有一个历史第一人的记录第一个能在30支球队都拿过40+的球员</p><p><br></p><p>蜗壳也只能做到对29支球队拿下40+记录就是用来打破，登哥不论多少记录资讯君心里火箭第一人，始终是姚明如今火箭12连败，怕是登哥三节打卡下班明个火箭篮网比赛下面公众号也能看<strong>体坛文明赏球&nbsp;</strong>狂热球迷聚集地，篮球、足球，甚至娱乐圈、INS各种“球”都要给你好看！男人的快乐就是这么简单！</p><p><br></p><p>登哥：兄弟们，撸起袖子给个机会全明星三分大赛也公布了参赛选手太阳核心布克，扣篮王拉文绿军布朗先生，爵士米切尔奶爸赖兔，小学生库里今年想扣篮的不去了简简单单凑齐三位扣将资讯君就说名字，看大家认识不尼克斯托平 ， 开拓者安芬尼西蒙斯第三位是来自步行者的卡修斯斯坦利</p><p><br></p><p>看一个个的表情就知道是肖华重金请来的克里斯保罗身为联盟主席疫情之下大力支持全明星为了不球迷们失望，决定亲自上阵看阵容，冠军感觉已经被内定</p>', '/api/upload/image_1642762217587.jpg', '2022年03月23日 12:51 新浪网');
INSERT INTO `article` VALUES (3, '杜锋：伤的伤停赛的停赛 只要进季后赛就可以', '运动', 531, 0, '2022-02-27 02:36:06', '2022-02-27 02:36:06', NULL, NULL, NULL, '<p class=\"ql-align-justify\">直播吧1月15日讯 CBA常规赛今天继续进行，广东男篮94比114不敌广厦男篮。赛后主教练<a href=\"https://www.163.com/keywords/6/5/675c950b/1.html\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 140, 210);\">杜锋</a>接受了媒体的采访。</p><p class=\"ql-align-justify\">杜锋谈到了这场失利：“球队现在进入了一个比较困难的时期，人员伤的伤、<a href=\"https://www.163.com/keywords/5/5/505c8d5b/1.html\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 140, 210);\">停赛</a>的停赛、生病的生病，周鹏、二飞、阿联和<a href=\"https://www.163.com/keywords/8/c/82cf4f1f/1.html\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 140, 210);\">苏伟</a>都是带伤在打球，越来越困难，但是我觉得大家在场上的态度还是非常好的。这个赛季的第二次两连败吧，输球倒问题不大，其实也说了，只要进季后赛就可以。希望在比赛过程当中年轻队员有更多的收获，特别是徐杰也好，还有小胡，希望他们通过比赛更快的成长起来，如果这样的话，输球就有价值。”</p>', '/api/upload/image_1642762283729.jpg', '2022年03月23日 12:51 新浪网');
INSERT INTO `article` VALUES (4, '测试运动会资讯', '资讯分类', 0, 1, '2022-02-27 11:05:47', '2022-02-27 11:08:52', '', '', '', '<p>测试</p><p><img src=\"data:image/jpeg;base64,\"></p><p>测试</p><p><img src=\"data:image/jpeg;base64,\"></p>', '/api/upload/0edd42f435b944a3069389289f50ec7f.jpg', '');

-- ----------------------------
-- Table structure for article_type
-- ----------------------------
DROP TABLE IF EXISTS `article_type`;
CREATE TABLE `article_type`  (
  `type_id` smallint(5) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '分类ID：[0,10000]',
  `display` smallint(4) UNSIGNED NOT NULL DEFAULT 100 COMMENT '显示顺序：[0,1000]决定分类显示的先后顺序',
  `name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称：[2,16]',
  `father_id` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '上级分类ID：[0,32767]',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述：[0,255]描述该分类的作用',
  `icon` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分类图标：',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外链地址：[0,255]如果该分类是跳转到其他网站的情况下，就在该URL上设置',
  `create_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间：',
  `update_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间：',
  PRIMARY KEY (`type_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文章频道：用于汇总浏览文章，在不同频道下展示不同文章。' ROW_FORMAT = Dynamic;

