  `competition_place` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '比赛地点',
  `game_time` datetime(0) NULL DEFAULT NULL COMMENT '比赛时间',
